<template><div v-loading="loading"><section class="card"><div class="card-heading"><div><h2>{{label(kind)}}申请与结果</h2><p>按开立时间排序，已收费项目可分配并登记</p></div><el-radio-group v-if="user.role_code==='ADMIN'" v-model="kind" @change="page=1;load()"><el-radio-button label="CHECK">检查</el-radio-button><el-radio-button label="LAB">检验</el-radio-button><el-radio-button label="TREAT">处置</el-radio-button></el-radio-group></div><div class="toolbar"><el-input v-model="search" clearable prefix-icon="el-icon-search" placeholder="姓名 / 病历号" @keyup.enter.native="page=1;load()"/><el-button @click="page=1;load()" icon="el-icon-search">查询</el-button><el-button @click="load" icon="el-icon-refresh">刷新</el-button></div><div class="inline-stats"><span>总项目 <b>{{records.total}}</b></span><span>本页已登记 <b>{{records.items.filter(o=>o.execution_status==='REGISTERED').length}}</b></span><span>本页已完成 <b>{{records.items.filter(o=>o.execution_status==='COMPLETED').length}}</b></span></div><el-table :data="records.items"><el-table-column type="expand"><template slot-scope="s"><div class="expand-info"><span>目的要求：{{s.row.purpose||'—'}}</span><span>部位：{{s.row.body_part||'—'}}</span><span>备注：{{s.row.notes||'—'}}</span><pre v-if="s.row.result_content" class="result-text">{{s.row.result_content}}</pre></div></template></el-table-column><el-table-column prop="patient_name" label="患者" width="90"/><el-table-column prop="case_no" label="病历号" min-width="180"/><el-table-column prop="item_name" label="项目" min-width="110"/><el-table-column label="申请时间" min-width="160"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column><el-table-column label="收费" width="100"><template slot-scope="s"><Status :value="s.row.billing_status"/></template></el-table-column><el-table-column label="执行" width="100"><template slot-scope="s"><Status :value="s.row.execution_status" execution/></template></el-table-column><el-table-column prop="executor_name" label="执行医生" width="100"/><el-table-column label="操作" fixed="right" width="120"><template slot-scope="s"><el-button v-if="s.row.billing_status==='PAID'&&s.row.execution_status==='PENDING'" type="text" @click="openRegister(s.row)">分配并登记</el-button><el-button v-if="s.row.execution_status==='REGISTERED'&&(user.role_code==='ADMIN'||s.row.executor_id===user.id)" type="text" @click="openResult(s.row)">录入结果</el-button><el-button v-if="s.row.result_content" type="text" @click="viewResult(s.row)">查看结果</el-button></template></el-table-column></el-table><el-pagination :current-page.sync="page" :page-size="20" :total="records.total" layout="total,prev,pager,next" @current-change="load"/></section>
<el-dialog title="分配并登记执行" :visible.sync="registerDialog" width="480px"><p v-if="selected"><b>{{selected.patient_name}}</b> · {{selected.item_name}}</p><el-alert title="登记后项目视为已消费，不能直接退费。" type="warning" :closable="false"/><el-form label-position="top" class="section-gap"><el-form-item label="执行科室"><el-input :value="selectedDept" disabled/></el-form-item><el-form-item label="执行医生"><el-select v-model="executorId" placeholder="选择本科室医生"><el-option v-for="u in executors" :key="u.id" :value="u.id" :label="u.display_name"/></el-select></el-form-item></el-form><span slot="footer"><el-button @click="registerDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="register">开始{{label(kind)}}</el-button></span></el-dialog>
<el-dialog :title="readOnly?'查看执行结果':'录入执行结果'" :visible.sync="resultDialog" width="650px"><div v-if="selected"><div class="report-heading"><h3>{{selected.item_name}}</h3><p>{{selected.patient_name}} · {{selected.case_no}} · {{selected.executor_name}}</p></div><el-input v-model="content" type="textarea" :rows="9" maxlength="8000" show-word-limit :readonly="readOnly" placeholder="填写结果内容，核对后提交"/></div><span slot="footer"><el-button @click="resultDialog=false">关闭</el-button><el-button v-if="!readOnly" type="primary" :loading="saving" @click="submitResult">提交结果</el-button></span></el-dialog></div></template>
<script>import{api,label,date}from'../api';import Status from'../components/Status.vue';export default{components:{Status},props:['catalog','user'],data:()=>({loading:false,saving:false,kind:'CHECK',search:'',page:1,records:{items:[],total:0},selected:null,registerDialog:false,resultDialog:false,executorId:'',content:'',readOnly:false}),computed:{selectedDept(){return this.catalog.departments.find(d=>d.id===this.selected?.department_id)?.name||'';},executors(){return this.catalog.staff.filter(u=>u.department_id===this.selected?.department_id&&u.role_code===this.kind);}},created(){this.kind=['CHECK','LAB','TREAT'].includes(this.user.role_code)?this.user.role_code:'CHECK';this.load();},methods:{label,date,async load(){this.loading=true;try{this.records=await api.get('/orders',{params:{kind:this.kind,q:this.search,page:this.page}});}catch{}finally{this.loading=false;}},openRegister(o){this.selected=o;this.executorId=this.executors.some(u=>u.id===this.user.id)?this.user.id:'';this.registerDialog=true;},openResult(o){this.selected=o;this.readOnly=false;this.content='';this.resultDialog=true;},viewResult(o){this.selected=o;this.readOnly=true;this.content=o.result_content;this.resultDialog=true;},async register(){if(!this.executorId)return this.$message.warning('请选择执行医生');this.saving=true;try{await api.post(`/orders/${this.selected.id}/register`,{executor_id:this.executorId});this.registerDialog=false;this.$message.success('项目已登记');await this.load();}catch{}finally{this.saving=false;}},async submitResult(){if(!this.content.trim())return this.$message.warning('请填写执行结果');this.saving=true;try{await api.post(`/orders/${this.selected.id}/result`,{content:this.content.trim()});this.resultDialog=false;this.$message.success('结果已回传医生工作站');await this.load();}catch{}finally{this.saving=false;}}}};</script>
